  const cs = Array.from(src)
  const n = cs.length
  // precompute positions
  const pos = new Array(n + 1)
  let line = 1, col = 1
  for (let k = 0; k < n; k++) {
    pos[k] = [line, col]
    if (cs[k] === '\n') { line++; col = 1 }
    else if (cs[k] === '\t') col = Math.floor((col - 1) / 4) * 4 + 5
    else col++
  }
  pos[n] = [line, col]
  const tokens = []
  let i = 0

  const digitRun = (j, ok) => {
    // digits with single '_' between two digits; returns end index (== j if none)
    if (!ok(cs[j])) return j
    j++
    while (j < n) {
      if (ok(cs[j])) j++
      else if (cs[j] === '_' && ok(cs[j + 1])) j += 2
      else break
    }
    return j
  }

  while (i < n) {
    const c = cs[i]
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') { i++; continue }
    if (c === '/' && cs[i + 1] === '/') {
      while (i < n && cs[i] !== '\n') i++
      continue
    }
    if (c === '/' && cs[i + 1] === '*') {
      const start = i
      let depth = 0
      while (true) {
        if (i >= n) throw new ScanError(start, 'unterminated block comment')
        if (cs[i] === '/' && cs[i + 1] === '*') { depth++; i += 2 }
        else if (cs[i] === '*' && cs[i + 1] === '/') { depth--; i += 2; if (depth === 0) break }
        else i++
      }
      continue
    }
    const start = i
    const at = pos[start]
    if (c === 'r' && cs[i + 1] === '"') {
      let j = i + 2
      while (j < n && cs[j] !== '"') j++
      if (j >= n) throw new ScanError(start, 'unterminated string')
      tokens.push([at, 'rawstring', JSON.stringify(cs.slice(i + 2, j).join(''))])
      i = j + 1
      continue
    }
    if (isLetter(c) || c === '_') {
      let j = i + 1
      while (j < n && isIdentChar(cs[j])) j++
      const text = cs.slice(i, j).join('')
      tokens.push([at, KEYWORDS.has(text) ? 'keyword' : 'ident', text])
      i = j
      continue
    }
    if (isDigit(c)) {
      let j = i
      let bad = false
      const p = cs[i + 1]
      const radix = c === '0' ? { x: isHex, X: isHex, b: (d) => d === '0' || d === '1', B: (d) => d === '0' || d === '1', o: (d) => d >= '0' && d <= '7' && d !== undefined, O: (d) => d >= '0' && d <= '7' && d !== undefined }[p] : undefined
