        j = digitRun(i + 2, radix)
        if (j === i + 2) bad = true
      } else {
        j = digitRun(i, isDigit)
        if (cs[j] === '.' && isDigit(cs[j + 1])) j = digitRun(j + 1, isDigit)
        if (cs[j] === 'e' || cs[j] === 'E') {
          if (isDigit(cs[j + 1])) j = digitRun(j + 1, isDigit)
          else if ((cs[j + 1] === '+' || cs[j + 1] === '-') && isDigit(cs[j + 2])) j = digitRun(j + 2, isDigit)
        }
      }
      if (bad || isIdentChar(cs[j])) {
        while (j < n && isIdentChar(cs[j])) j++
        throw new ScanError(start, `invalid number ${cs.slice(i, j).join('')}`)
      }
      tokens.push([at, 'number', cs.slice(i, j).join('')])
      i = j
      continue
    }
    if (c === '"') {
      let j = i + 1
      let out = ''
      while (true) {
        if (j >= n) throw new ScanError(start, 'unterminated string')
        const d = cs[j]
        if (d === '"') { j++; break }
        if (d === '\n') throw new ScanError(j, 'newline in string')
        if (d !== '\\') { out += d; j++; continue }
        const e = cs[j + 1]
        if (e === undefined) throw new ScanError(start, 'unterminated string')
        const simple = { n: '\n', t: '\t', r: '\r', '\\': '\\', '"': '"', '0': '\0' }
        if (Object.hasOwn(simple, e)) { out += simple[e]; j += 2; continue }
