          if (isHex(cs[j + 2]) && isHex(cs[j + 3])) {
            out += String.fromCodePoint(parseInt(cs[j + 2] + cs[j + 3], 16)); j += 4; continue
          }
          throw new ScanError(j, 'invalid escape \\x')
        }
        if (e === 'u' && cs[j + 2] === '{') {
          let k = j + 3
          let h = ''
          while (isHex(cs[k])) h += cs[k++]
