          }
          throw new ScanError(j, 'invalid escape \\u')
        }
        throw new ScanError(j, `invalid escape \\${e}`)
      }
      tokens.push([at, 'string', JSON.stringify(out)])
      i = j
      continue
    }
    const two = c + (cs[i + 1] ?? '')
    const p = PUNCT.find((x) => x === two) ?? PUNCT.find((x) => x === c)
